public sealed record CreateUserRequest
{
    [Required, StringLength(100, MinimumLength = 2)]
    public string Name { get; init; } = "";

    [Required, EmailAddress]
    public string Email { get; init; } = "";

    [Range(13, 120, ErrorMessage = "Age must be between 13 and 120.")]
    public int Age { get; init; }

    [RegularExpression(@"^(?=.*[A-Z])(?=.*\d).{8,}$")]
    public string Password { get; init; } = "";
}

[ApiController]
[Route("api/users")]
public class UsersController : ControllerBase
{
    [HttpPost]
    public IActionResult Create([FromBody] CreateUserRequest request)
    {
        // ModelState already validated — only reached when valid
        return Created($"/api/users/1", request);
    }
}

public sealed record DateRangeRequest : IValidatableObject
{
    [Required] public DateOnly Start { get; init; }
    [Required] public DateOnly End { get; init; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (End < Start)
        {
            yield return new ValidationResult(
                "End must be on or after Start.",
                [nameof(Start), nameof(End)]);
        }
    }
}

app.MapPost("/legacy/users", (CreateUserRequest request, HttpContext http) =>
{
    // Minimal APIs: annotations run only if you validate explicitly
    var context = new ValidationContext(request);
    var results = new List<ValidationResult>();
    if (!Validator.TryValidateObject(request, context, results, validateAllProperties: true))
    {
        var errors = results.ToDictionary(
            r => r.MemberNames.FirstOrDefault() ?? "",
            r => new[] { r.ErrorMessage ?? "Invalid." });
        return Results.ValidationProblem(errors);
    }
    return Results.Created("/users/1", request);
});

[Fact]
public async Task Invalid_email_returns_validation_problem_details()
{
    await using var factory = new WebApplicationFactory<Program>();
    var client = factory.CreateClient();
    var response = await client.PostAsJsonAsync("/api/users",
        new { name = "A", email = "not-an-email", age = 5, password = "weak" });

    Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
    var doc = await response.Content.ReadFromJsonAsync<JsonElement>();
    Assert.True(doc.TryGetProperty("errors", out var errors));
    Assert.True(errors.TryGetProperty("Email", out _));
